package com.acetelecom.repairdesk.common.domain;

import java.time.Instant;
import java.util.UUID;

import jakarta.persistence.Column;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.MappedSuperclass;
import jakarta.persistence.PrePersist;
import jakarta.persistence.Version;
import lombok.Getter;
import lombok.Setter;

/**
 * CORE-003: Shared base for all mutable JPA entities.
 *
 * <ul>
 *   <li>UUID primary key — generated by the JPA provider (delegating to PostgreSQL
 *       {@code gen_random_uuid()} via {@code GenerationType.UUID}).</li>
 *   <li>{@code created_at} — set once at construction; not updatable.</li>
 *   <li>{@code updated_at} — set by the service before every {@code save()}.</li>
 *   <li>{@code version} — JPA {@code @Version} for optimistic locking; conflicts
 *       surface as {@code 409 CONFLICT} via the global exception handler.</li>
 * </ul>
 */
@MappedSuperclass
@Getter
@Setter
public abstract class BaseEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.UUID)
    private UUID id;

    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt = Instant.now();

    @Column(name = "updated_at")
    private Instant updatedAt;

    @Version
    private long version;

    /** A row that has never been edited keeps updated_at equal to created_at. */
    @PrePersist
    void stampUpdatedAtOnCreate() {
        if (createdAt == null) {
            createdAt = Instant.now();
        }
        if (updatedAt == null) {
            updatedAt = createdAt;
        }
    }
}
